import { Hono } from 'hono'
import {
  createDirectSale,
  voidSale,
  type SaleResult,
  InsufficientStockError,
  SaleNotFoundError,
  listSales,
  findSaleById,
  findLineItemsBySaleId,
  findPaymentsBySaleId,
  findMovementsBySaleId
} from '../services/sale.service.js'

const salesRoutes = new Hono()

// ============================================================================
// POST /sales — Create a direct sale
// ============================================================================

/**
 * Error response shape.
 */
interface ErrorResponse {
  error: string
  code?: string
  shortfalls?: Array<{ partId: string; requested: number; available: number }>
}

salesRoutes.post('/', async (c) => {
  try {
    const rawInput = await c.req.json()

    const result: SaleResult = await createDirectSale(rawInput)

    return c.json(
      {
        sale: Object.fromEntries(Object.entries(result.sale)),
        payment: Object.fromEntries(Object.entries(result.payment)),
        lineItems: result.lineItems.map(item => Object.fromEntries(Object.entries(item)))
      },
      201
    )
  } catch (err) {
    if (err instanceof InsufficientStockError) {
      return c.json(
        {
          error: 'Insufficient stock',
          code: 'INSUFFICIENT_STOCK',
          shortfalls: err.shortfalls
        } as ErrorResponse,
        409
      )
    }

    if (err instanceof Error && err.message.startsWith('Invalid sale input')) {
      return c.json(
        { error: err.message, code: 'VALIDATION_ERROR' } as ErrorResponse,
        400
      )
    }

    console.error('[POST /sales] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

// ============================================================================
// GET /sales — List recent sales history
// ============================================================================

interface SalesListResponse {
  /** Array of sale records (newest first) */
  sales: Record<string, unknown>[]
  /** Total count of all sales */
  total: number
}

salesRoutes.get('/', async (c) => {
  const limit = Math.min(parseInt(c.req.query('limit') ?? '50', 10) || 50, 200)

  const saleRows = await listSales(limit)
  const total = await listSales(999999).then(rows => rows.length)

  return c.json({
    sales: saleRows.map(row => Object.fromEntries(Object.entries(row))),
    total
  } as SalesListResponse)
})

// ============================================================================
// GET /sales/:id — Get a single sale with full details
// ============================================================================

interface SaleDetailResponse {
  /** The sale header */
  sale: Record<string, unknown>
  /** Line items for this sale */
  lineItems: Record<string, unknown>[]
  /** Payments allocated to this sale */
  payments: Record<string, unknown>[]
  /** Stock movements referencing this sale */
  stockMovements: Record<string, unknown>[]
}

salesRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')

  const sale = await findSaleById(id)
  if (!sale) {
    return c.json({ error: 'Sale not found', code: 'NOT_FOUND' }, 404)
  }

  const [lineItems, payments, stockMovements] = await Promise.all([
    findLineItemsBySaleId(id),
    findPaymentsBySaleId(id),
    findMovementsBySaleId(id)
  ])

  return c.json({
    sale: Object.fromEntries(Object.entries(sale)),
    lineItems: lineItems.map(item => Object.fromEntries(Object.entries(item))),
    payments: payments.map(payment => Object.fromEntries(Object.entries(payment))),
    stockMovements: stockMovements.map(mvmt => Object.fromEntries(Object.entries(mvmt)))
  } as SaleDetailResponse)
})

// ============================================================================
// PATCH /sales/:id/void — Void a completed sale
// ============================================================================

salesRoutes.patch('/:id/void', async (c) => {
  const id = c.req.param('id')

  try {
    const updatedSale = await voidSale(id)

    return c.json({
      sale: Object.fromEntries(Object.entries(updatedSale))
    })
  } catch (err) {
    if (err instanceof SaleNotFoundError) {
      return c.json(
        { error: 'Sale not found', code: 'NOT_FOUND' },
        404
      )
    }

    if (err instanceof Error && err.message.includes('already voided')) {
      return c.json(
        { error: err.message, code: 'ALREADY_VOIDED' },
        409
      )
    }

    console.error('[PATCH /sales/:id/void] Unexpected error:', err)
    return c.json(
      { error: 'Internal server error', code: 'INTERNAL_ERROR' },
      500
    )
  }
})

